export function getZodiac(month, day) {
  const signs = [
    { m: 1,  d: 20, ja: '山羊座', en: 'Capricorn',   es: 'Capricornio', zh: '摩羯座', ko: '염소자리', pt: 'Capricórnio', symbol: '♑' },
    { m: 2,  d: 19, ja: '水瓶座', en: 'Aquarius',    es: 'Acuario',     zh: '水瓶座', ko: '물병자리', pt: 'Aquário',     symbol: '♒' },
    { m: 3,  d: 21, ja: '魚座',   en: 'Pisces',      es: 'Piscis',      zh: '双鱼座', ko: '물고기자리', pt: 'Peixes',    symbol: '♓' },
    { m: 4,  d: 20, ja: '牡羊座', en: 'Aries',       es: 'Aries',       zh: '白羊座', ko: '양자리',   pt: 'Áries',      symbol: '♈' },
    { m: 5,  d: 21, ja: '牡牛座', en: 'Taurus',      es: 'Tauro',       zh: '金牛座', ko: '황소자리', pt: 'Touro',      symbol: '♉' },
    { m: 6,  d: 21, ja: '双子座', en: 'Gemini',      es: 'Géminis',     zh: '双子座', ko: '쌍둥이자리', pt: 'Gêmeos',   symbol: '♊' },
    { m: 7,  d: 23, ja: '蟹座',   en: 'Cancer',      es: 'Cáncer',      zh: '巨蟹座', ko: '게자리',   pt: 'Câncer',     symbol: '♋' },
    { m: 8,  d: 23, ja: '獅子座', en: 'Leo',         es: 'Leo',         zh: '狮子座', ko: '사자자리', pt: 'Leão',       symbol: '♌' },
    { m: 9,  d: 23, ja: '乙女座', en: 'Virgo',       es: 'Virgo',       zh: '处女座', ko: '처녀자리', pt: 'Virgem',     symbol: '♍' },
    { m: 10, d: 23, ja: '天秤座', en: 'Libra',       es: 'Libra',       zh: '天秤座', ko: '천칭자리', pt: 'Libra',      symbol: '♎' },
    { m: 11, d: 22, ja: '蠍座',   en: 'Scorpio',     es: 'Escorpio',    zh: '天蝎座', ko: '전갈자리', pt: 'Escorpião',  symbol: '♏' },
    { m: 12, d: 22, ja: '射手座', en: 'Sagittarius', es: 'Sagitario',   zh: '射手座', ko: '사수자리', pt: 'Sagitário',  symbol: '♐' },
    { m: 12, d: 32, ja: '山羊座', en: 'Capricorn',   es: 'Capricornio', zh: '摩羯座', ko: '염소자리', pt: 'Capricórnio', symbol: '♑' },
  ];
  for (const s of signs) {
    if (month < s.m || (month === s.m && day < s.d)) return s;
  }
  return signs[0];
}

