  '6-4': [{ type: 'sad', year: '1989', text: { ja: '天安門広場で民主化を求める学生たちが軍により弾圧された', en: 'Pro-democracy protesters were violently suppressed in Tiananmen Square, Beijing' } }, { type: 'happy', year: '1942', text: { ja: 'ミッドウェー海戦で連合国が勝利し、太平洋戦争の転換点となった', en: 'The Battle of Midway turned the tide of the Pacific War in favor of the Allies' } }],
  '6-6': [{ type: 'happy', year: '1944', text: { ja: 'Dデー（ノルマンディー上陸作戦）が決行され、ヨーロッパ解放への決定的な一歩となった', en: 'D-Day - Allied forces landed in Normandy, France, a decisive step toward liberating Europe' } }, { type: 'sad', year: '1944', text: { ja: '上陸作戦では多くの兵士が命を犠牲にして自由のために戦った', en: 'Thousands of soldiers gave their lives in the D-Day landings fighting for freedom' } }],
