  '7-7': [{ type: 'sad', year: '2005', text: { ja: 'ロンドンで同時爆破テロが発生し、52人が命を落とした', en: 'Coordinated bombings struck London, killing 52 people and injuring hundreds' } }, { type: 'happy', year: '2005', text: { ja: 'ロンドン市民はテロに屈せず、翌日から普段通りの生活を取り戻した', en: 'Londoners refused to be defeated by terrorism and returned to normal life the very next day' } }],
