  '8-9': [{ type: 'sad', year: '1945', text: { ja: '長崎に2発目の原子爆弾が投下され、多くの命が失われた', en: 'The second atomic bomb was dropped on Nagasaki, Japan, ending WWII but at a tremendous cost' } }, { type: 'happy', year: '1974', text: { ja: 'ウォーターゲート事件でニクソン大統領が辞任し、民主主義の機能を示した', en: 'President Nixon resigned over Watergate, demonstrating democracy\'s ability to hold leaders accountable' } }],
