  '9-11': [{ type: 'sad', year: '2001', text: { ja: 'アメリカで同時多発テロが発生し、世界が大きく変わった', en: 'The September 11 attacks struck the United States, changing the world forever' } }, { type: 'happy', year: '2001', text: { ja: '世界中の人々が助け合い、テロに屈しない人間の強さを示した', en: 'People around the world united in solidarity and compassion in response to the attacks' } }],
