  '10-24': [{ type: 'happy', year: '1945', text: { ja: '国際連合が設立され、世界平和と国際協力の新たな枠組みが生まれた', en: 'The United Nations was established, creating a new framework for world peace and international cooperation' } }, { type: 'sad', year: '1929', text: { ja: '「暗黒の木曜日」ニューヨーク株式市場が大暴落し、世界大恐慌が始まった', en: '"Black Thursday" - the New York Stock Exchange crashed, beginning the Great Depression' } }],
