  '11-11': [{ type: 'sad', year: '1918', text: { ja: '第一次世界大戦が終結した。4年間の戦争で約1,700万人の命が失われた', en: 'World War I ended. Over 17 million lives were lost in four years of devastating warfare' } }, { type: 'happy', year: '1918', text: { ja: 'ついに戦争が終わり、世界中の人々が平和を喜んだ', en: 'Peace finally came, and people around the world celebrated the end of the Great War' } }],
